# Lesson 3.7: images (img, src, alt, width in px and %) and favicons (link rel=icon in the head)
L = lambda *a: '\n'.join(a)
def P(title, story, code, dis): return (title, story, code, dis)
U = lambda n: 'https://images.example.org/%s.png' % n
